{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/pricing-card.json
    A plan as a card: name, tagline, price per month, the features, a call to action and an optional slot for more actions. Text comes in through `labels`; the plan is data.
    Props (p): plan, labels, current, emphasis, density, billing, footer (slot: plan). -#}
{%- set v_plan = (p.plan ?? null) -%}
{%- set v_labels = (p.labels ?? null) -%}
{%- set v_current = (p.current ?? null) -%}
{%- set v_emphasis = (p.emphasis ?? 'auto') -%}
{%- set v_density = (p.density ?? 'default') -%}
{%- set v_billing = (p.billing ?? 'monthly') -%}
{%- set v_stand = ui_and([ui_get(v_plan, ['highlighted']), ui_eq(v_emphasis, 'auto')]) -%}
{%- set v_yearlyOn = ui_and([ui_eq(v_billing, 'annual'), ui_gt(ui_get(v_plan, ['yearly']), 0)]) -%}
{%- set v_amount = (ui_t(v_yearlyOn) ? ui_get(v_plan, ['yearly']) : ui_get(v_plan, ['price'])) -%}
{%- set c_16 -%}
  {%- set c_5 -%}
    {%- set c_2 -%}
      {%- if ui_t(v_stand) %}
        {%- set c_1 -%}
          {{ ui_text(ui_get(v_labels, ['popular'])) }}
