      {%- endif %}
    {%- endset -%}
    {{ include('ui/box/box.html.twig', {'p': {'Class': 'flex min-h-6 items-center', 'Attrs': ui_attrs(['data-slot', 'badge-slot'])}, 'children': c_2}, with_context = false) }}
    {%- set c_3 -%}
      {{ ui_text(ui_get(v_plan, ['name'])) }}
    {%- endset -%}
    {{ include('ui/card/card-title.html.twig', {'p': {'As': ui_i(3)}, 'children': c_3}, with_context = false) }}
    {%- set c_4 -%}
