    {%- if (p.footer ?? null) is not null %}
      {{ include(p.footer.t, p.footer.v|merge({'a0': v_plan}), with_context = false) }}
    {%- endif %}
  {%- endset -%}
  {{ include('ui/card/card-footer.html.twig', {'p': {'Class': 'flex flex-wrap items-center gap-2'}, 'children': c_15}, with_context = false) }}
{%- endset -%}
